def run_letter_migration(apps, schema_editor):
    Letter = apps.get_model("edwoca", "Letter")
    LetterWorkReference = apps.get_model("edwoca", "LetterWorkReference")

    parser = Lark(
        ebnf_grammar,
        start="textfield",
        parser="lalr",
        transformer=FastHistoricalTransformer(),
    )

    legacy_field_name = "work_mentionings"

    letters_qs = (
        Letter.objects.exclude(**{f"{legacy_field_name}__isnull": True})
        .exclude(**{f"{legacy_field_name}__exact": ""})
        .iterator(chunk_size=500)
    )

    batch = []
    error_count = 0
    success_count = 0

    for letter in letters_qs:
        raw_text = getattr(letter, legacy_field_name, None)
        if not raw_text or not raw_text.strip():
            continue

        try:
            parsed_entries = parser.parse(raw_text.strip())
            for entry_data in parsed_entries:
                entry_data["letter_id"] = letter.id
                batch.append(LetterWorkReference(**entry_data))
                success_count += 1
        except Exception as e:
            error_count += 1
            print(f"[PARSER ERROR] Letter ID {letter.id}: {e} | Text: {repr(raw_text[:80])}")

        if len(batch) >= 1000:
            LetterWorkReference.objects.bulk_create(batch)
            batch.clear()

    if batch:
        LetterWorkReference.objects.bulk_create(batch)

    print(f"\nMigration abgeschlossen: {success_count} Datensätze erstellt, {error_count} Fehler.")


